-- Actions look like "<entity>.<verb>", for example "event.updated" (D-037).
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_action_format"
  CHECK ("action" ~ '^[a-z_]+\.[a-z_]+$');

