ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_entity_pair"
  CHECK (("entityType" IS NULL) = ("entityId" IS NULL));

-- The audit log is append-only (D-037). Direct UPDATE and DELETE statements are rejected. Changes
-- made by a foreign key action are allowed: deleting an event removes its log (D-004), and deleting
-- a user sets actorId to NULL. Those run inside the foreign key's own trigger, so the trigger depth
-- is 2 or more; a statement from the application runs at depth 1.
CREATE FUNCTION eventops_audit_logs_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF pg_trigger_depth() < 2 THEN
    RAISE EXCEPTION 'audit_logs_append_only: audit log entries cannot be changed or deleted'
      USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "audit_logs_append_only"
  BEFORE UPDATE OR DELETE ON "audit_logs"
  FOR EACH ROW EXECUTE FUNCTION eventops_audit_logs_append_only();